def report(name,pattern):
    print(f"--- {name} ({pattern}) ---")
    for lbl,s in (("+",seq),("-",rc)):
        for m in re.finditer(pattern,s):
            if lbl=="+": g1,g2=m.start()+1,m.end()
            else:        g1,g2=len(seq)-m.end()+1,len(seq)-m.start()
            print(f"  strand{lbl}: genomic {g1}-{g2}  motif {m.group()}")

for name,pat in [
    ("TATA box","TATA[AT]A"),
    ("Kozak (GCCACC)","GCCACC"),
    ("Shine-Dalgarno AGGAGG","AGGAGG"),
    ("bact -35 TTGACA","TTGACA"),
    ("bact -10 TATAAT","TATAAT"),
    ("Pribnow TAtaaT","TA[AC]A[AT]T"),
    ("APE1 CPE (TTTATATAP)","TTT[Aa]TATA"),
    ("E2F/motif TTTCGCGC","TTTCGCGC"),
    ("GC box GGGCGG","GGGCGG"),
    ("CPG island CpG","CG"),
    ("MluI cell-cycle site ACGCGT","ACGCGT"),
    ("E-box CACCTG","CACCTG"),
]:
    report(name,pat)

# AATAA positions for polyA-signal analysis (logistic 'AATAAA' known polyA)
print("\nAATAAA sites (canonical eukaryotic polyA signal):")
